#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> step(const vector<int>& a, const string& op) {
    vector<vector<int>> res;
    vector<int> perm = a;
    sort(perm.begin(), perm.end());
    do {
        int first = perm[0];
        int second = perm[1];
        int val = (op == "+") ? first + second : first * second;
        vector<int> v;
        v.push_back(val);
        for (size_t i = 2; i < perm.size(); ++i) {
            v.push_back(perm[i]);
        }
        sort(v.begin(), v.end());
        res.push_back(v);
    } while (next_permutation(perm.begin(), perm.end()));
    sort(res.begin(), res.end());
    res.erase(unique(res.begin(), res.end()), res.end());
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> a;
    {
        string line;
        if (!getline(cin, line)) return 0;
        stringstream ss(line);
        int x;
        while (ss >> x) a.push_back(x);
    }

    vector<string> oper;
    {
        string line;
        if (!getline(cin, line)) return 0;
        stringstream ss(line);
        string s;
        while (ss >> s) oper.push_back(s);
    }

    vector<int> res;
    vector<vector<int>> first = step(a, oper[0]);
    for (const auto& v : first) {
        vector<vector<int>> second = step(v, oper[1]);
        for (const auto& t : second) {
            vector<vector<int>> third = step(t, oper[2]);
            for (const auto& u : third) {
                for (int x : u) res.push_back(x);
            }
        }
    }

    if (!res.empty()) {
        cout << *min_element(res.begin(), res.end()) << '\n';
    }

    return 0;
}

